      "percentAchieved": "9.1%",
      "gamerscore": 10,
      "guideDescription": "To unlock the \"Medal Master Chief\" achievement in Halo: The Master Chief Collection (MCC), you’ll need to collect 8000 campaign or playlist medals. These medals can be earned while playing the campaign or participating in matchmaking. To maximize your progress, focus on killing enemies swiftly and efficiently, aiming for multi-kill and killing spree medals. Playing on Easy difficulty in the campaign is recommended, as it allows you to accumulate medals without the added challenge of higher difficulties.",
